function setLanguage(next){lang=next;document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(el=>{const value=translations[lang][el.dataset.i];if(value!==undefined)el.innerHTML=value});const language=document.getElementById('lang');language.textContent=lang==='ru'?'EN':'RU';language.setAttribute('aria-label',lang==='ru'?'Switch language to English':'Переключить язык на русский');if(window.lucide)lucide.createIcons();try{localStorage.setItem('modexa-language',lang)}catch(_){}}
