const cookie=document.getElementById('cookieBanner'),accept=document.getElementById('cookieAccept'),dismiss=document.getElementById('cookieDismiss');const consentKey='cookie_accepted';
function activateAnalytics(){/* Add Yandex.Metrica / Google Analytics initialization here. Any script insertion or network request must stay inside this function so analytics runs only after consent. */}
function hideCookie(){cookie.classList.add('is-hiding');cookie.classList.remove('visible');cookie.setAttribute('aria-hidden','true');setTimeout(()=>{cookie.hidden=true},320)}
let accepted=false;try{accepted=localStorage.getItem(consentKey)==='true'}catch(_){}
if(accepted){activateAnalytics()}else{setTimeout(()=>{cookie.classList.add('visible');cookie.setAttribute('aria-hidden','false')},500)}
accept.addEventListener('click',()=>{try{localStorage.setItem(consentKey,'true')}catch(_){}hideCookie();activateAnalytics()});dismiss.addEventListener('click',hideCookie);
if(window.lucide)lucide.createIcons();
